
.greeting-index-scrim {
  position: fixed;
  z-index: 9100;
  inset: 0;
  display: grid;
  place-items: center;
  padding: 14px;
  outline: 0;
  background: color-mix(in srgb, var(--stage-shadow) 78%, transparent);
  backdrop-filter: blur(7px);
}

.greeting-index-dialog {
  width: min(720px, 100%);
  max-height: calc(100% - 4px);
  display: flex;
  flex-direction: column;
  overflow: hidden;
  border: 1px solid var(--line-strong);
  border-radius: 8px;
  color: var(--text-primary);
  background: color-mix(in srgb, var(--surface-raised) 97%, transparent);
  box-shadow:
    0 28px 74px var(--stage-shadow),
    inset 0 0 0 1px var(--line-subtle);
}

.greeting-index-dialog > header {
  min-height: 58px;
  padding: 0 14px 0 16px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  flex: 0 0 auto;
  border-bottom: 1px solid var(--line-subtle);
  background: var(--header-bg);
}

.dialog-heading,
.dialog-heading > span:last-child {
  min-width: 0;
  display: flex;
  align-items: center;
}
.dialog-heading {
  gap: 10px;
}
.dialog-heading > span:last-child {
  align-items: flex-start;
  flex-direction: column;
  gap: 2px;
}
.dialog-heading strong {
  color: var(--text-accent);
  font-size: 15px;
}
.dialog-heading small {
  color: var(--text-secondary);
  font-size: 10px;
}
.heading-mark {
  width: 31px;
  height: 31px;
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  border: 1px solid color-mix(in srgb, var(--gold) 38%, var(--line-subtle));
  border-radius: 50%;
  color: var(--gold);
  background: color-mix(in srgb, var(--gold) 9%, var(--surface-inset));
}
.close-button {
  width: 32px;
  height: 32px;
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  border: 1px solid var(--line-subtle);
  border-radius: 5px;
  color: var(--text-secondary);
  background: var(--surface-inset);
  cursor: pointer;
}
.close-button:hover {
  border-color: var(--line-strong);
  color: var(--gold);
}

.greeting-search {
  min-height: 38px;
  margin: 10px 12px 4px;
  padding: 0 11px;
  display: flex;
  align-items: center;
  gap: 9px;
  flex: 0 0 auto;
  border: 1px solid var(--line-subtle);
  border-radius: 6px;
  color: var(--text-secondary);
  background: var(--surface-inset);
}
.greeting-search:focus-within {
  border-color: color-mix(in srgb, var(--gold) 54%, var(--line-strong));
}
.greeting-search input {
  min-width: 0;
  flex: 1;
  border: 0;
  outline: 0;
  color: var(--text-primary);
  background: transparent;
  font: inherit;
}
.greeting-search input::placeholder {
  color: var(--text-secondary);
}
.greeting-search span {
  font-size: 10px;
  font-variant-numeric: tabular-nums;
}

.greeting-list {
  min-height: 0;
  padding: 8px 12px 12px;
  display: grid;
  gap: 6px;
  overflow: auto;
  overscroll-behavior: contain;
  scrollbar-color: var(--line-strong) transparent;
  scrollbar-width: thin;
}
.greeting-row {
  width: 100%;
  min-height: 62px;
  padding: 8px 10px;
  display: grid;
  grid-template-columns: 34px minmax(0, 1fr) 16px;
  align-items: center;
  gap: 10px;
  border: 1px solid var(--line-subtle);
  border-radius: 6px;
  color: var(--text-primary);
  background: color-mix(in srgb, var(--surface-inset) 80%, transparent);
  text-align: left;
  cursor: pointer;
  transition:
    border-color 120ms ease,
    background 120ms ease,
    transform 120ms ease;
}
.greeting-row:hover:not(:disabled) {
  border-color: var(--line-strong);
  background: var(--button-hover);
  transform: translateX(2px);
}
.greeting-row.current {
  border-color: color-mix(in srgb, var(--jade) 46%, var(--line-strong));
  background: color-mix(in srgb, var(--jade) 8%, var(--surface-inset));
}
.greeting-row:disabled {
  cursor: wait;
}
.greeting-row:disabled:not(.busy) {
  opacity: 0.5;
}
.greeting-number {
  width: 32px;
  height: 25px;
  display: grid;
  place-items: center;
  border: 1px solid color-mix(in srgb, var(--gold) 34%, var(--line-subtle));
  border-radius: 999px;
  color: var(--gold);
  background: color-mix(in srgb, var(--gold) 8%, transparent);
  font-size: 11px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}
.greeting-copy {
  min-width: 0;
  display: grid;
  gap: 4px;
}
.greeting-title {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 7px;
}
.greeting-title strong {
  min-width: 0;
  overflow: hidden;
  color: var(--text-accent);
  font-size: 13px;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.greeting-title small {
  padding: 1px 5px;
  flex: 0 0 auto;
  border-radius: 999px;
  color: var(--jade);
  background: color-mix(in srgb, var(--jade) 12%, transparent);
  font-size: 9px;
}
.greeting-preview {
  overflow: hidden;
  color: var(--text-secondary);
  font-size: 10px;
  line-height: 1.5;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.row-action {
  color: var(--text-secondary);
  font-size: 10px;
}
.greeting-row:hover .row-action,
.greeting-row.current .row-action {
  color: var(--gold);
}

.greeting-empty {
  min-height: 190px;
  padding: 26px;
  display: grid;
  place-items: center;
  align-content: center;
  gap: 8px;
  color: var(--text-secondary);
  text-align: center;
}
.greeting-empty > i {
  margin-bottom: 4px;
  color: var(--gold);
  font-size: 26px;
  opacity: 0.72;
}
.greeting-empty strong {
  color: var(--text-accent);
}
.greeting-empty span {
  font-size: 10px;
}

.greeting-index-fade-enter-active,
.greeting-index-fade-leave-active {
  transition: opacity 160ms ease;
}
.greeting-index-fade-enter-from,
.greeting-index-fade-leave-to {
  opacity: 0;
}

@media screen and (max-width: 620px) {
  .greeting-index-scrim {
    padding: 8px;
  }
  .greeting-index-dialog {
    max-height: calc(100% - 2px);
  }
  .greeting-index-dialog > header {
    min-height: 52px;
    padding: 0 10px 0 12px;
  }
  .heading-mark {
    display: none;
  }
  .greeting-search {
    margin: 8px 8px 3px;
  }
  .greeting-list {
    padding: 6px 8px 8px;
    gap: 5px;
  }
  .greeting-row {
    min-height: 58px;
    grid-template-columns: 30px minmax(0, 1fr) 12px;
    gap: 8px;
    padding: 7px 8px;
  }
  .greeting-number {
    width: 29px;
  }
}
