
.stage-header {
  position: relative;
  min-height: 66px;
  display: grid;
  grid-template-columns: minmax(260px, 1fr) minmax(260px, 1.1fr) minmax(260px, 1fr);
  align-items: center;
  gap: 18px;
  padding: 8px 14px;
  border-bottom: 1px solid var(--line-strong);
  background: var(--header-bg);
  box-shadow:
    inset 0 -1px 0 color-mix(in srgb, var(--gold) 12%, transparent),
    0 8px 26px color-mix(in srgb, var(--stage-shadow) 54%, transparent);
  overflow: hidden;
}

.stage-header::before {
  content: '';
  position: absolute;
  inset: 0;
  background:
    linear-gradient(
      90deg,
      transparent 0 5%,
      color-mix(in srgb, var(--gold) 7%, transparent) 18%,
      transparent 34% 66%,
      color-mix(in srgb, var(--jade) 6%, transparent) 82%,
      transparent 95%
    ),
    var(--grain-material);
  pointer-events: none;
}

.stage-header::after {
  content: '';
  position: absolute;
  right: 50%;
  bottom: -1px;
  width: 76px;
  height: 2px;
  transform: translateX(50%);
  background: linear-gradient(90deg, transparent, var(--gold), transparent);
  opacity: 0.62;
}

.stage-header > * {
  position: relative;
  z-index: 1;
}

.turn-cluster,
.turn-navigation,
.reading-mode-switch,
.stage-utilities {
  display: flex;
  align-items: center;
}
.turn-cluster {
  min-width: 0;
  gap: 9px;
}
.crane-mark {
  width: 34px;
  height: 34px;
  flex-shrink: 0;
  object-fit: contain;
  filter: drop-shadow(0 3px 8px var(--stage-shadow)) sepia(0.16);
}
.turn-copy {
  min-width: 74px;
  display: grid;
  gap: 1px;
}
.turn-copy span {
  color: var(--gold-soft);
  font-family: 'Songti SC', 'STSong', serif;
  font-size: 10px;
}
.turn-copy strong {
  max-width: 150px;
  overflow: hidden;
  color: var(--text-primary);
  font-size: 13px;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.turn-token-count {
  width: max-content;
  color: var(--text-secondary);
  font-family: ui-monospace, 'SFMono-Regular', Consolas, monospace;
  font-size: 9px;
  line-height: 1;
}
.turn-navigation {
  gap: 3px;
}
.reading-mode-switch {
  flex: 0 0 auto;
  gap: 2px;
  padding: 2px;
  border: 1px solid var(--line-subtle);
  border-radius: 6px;
  background: color-mix(in srgb, var(--surface-inset) 68%, transparent);
}
.turn-navigation span {
  min-width: 36px;
  color: var(--text-secondary);
  font-size: 10px;
  text-align: center;
  font-variant-numeric: tabular-nums;
}

.turn-navigation button,
.reading-mode-switch button,
.stage-utilities button {
  width: 30px;
  height: 30px;
  display: grid;
  place-items: center;
  border: 1px solid var(--line-subtle);
  border-radius: 5px;
  color: var(--text-secondary);
  background: color-mix(in srgb, var(--surface-inset) 72%, transparent);
  box-shadow: inset 0 1px 0 color-mix(in srgb, var(--text-primary) 4%, transparent);
  cursor: pointer;

  &:hover:not(:disabled) {
    border-color: var(--line-strong);
    color: var(--gold);
    background: var(--button-hover);
  }
  &:disabled {
    opacity: 0.28;
    cursor: not-allowed;
  }
}
.reading-mode-switch button {
  width: 26px;
  height: 26px;
  border: 0;
  background: transparent;
  box-shadow: none;
}
.reading-mode-switch button.active {
  color: var(--gold);
  background: var(--button-active);
}

.scene-location {
  min-width: 0;
  display: grid;
  justify-items: center;
  gap: 3px;
  padding: 6px 10px;
  border: 0;
  color: var(--text-primary);
  background: transparent;
  cursor: pointer;
  text-shadow: 0 1px 10px var(--stage-shadow);
}
.scene-kicker {
  color: var(--text-secondary);
  font-size: 9px;
}
.scene-location strong {
  max-width: 100%;
  overflow: hidden;
  color: var(--gold);
  font-family: 'Songti SC', 'STSong', serif;
  font-size: 15px;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.scene-location-compact {
  display: none;
}
.scene-location strong i {
  margin-right: 5px;
  color: var(--jade);
}
.scene-location strong span {
  color: var(--text-accent);
  font-weight: 400;
}
.scene-location strong b {
  padding: 0 5px;
  color: var(--text-secondary);
  font-weight: 400;
}

.stage-utilities {
  min-width: 0;
  justify-content: flex-end;
  gap: 5px;
}
.mobile-tool-group {
  display: none;
}
.danger-badge {
  margin-right: 4px;
  padding: 4px 8px;
  border: 1px solid color-mix(in srgb, var(--danger-color) 60%, transparent);
  border-radius: 999px;
  color: var(--danger-color);
  background: color-mix(in srgb, var(--danger-color) 10%, transparent);
  font-size: 10px;
  white-space: nowrap;
}
.delete-button:hover:not(:disabled) {
  border-color: color-mix(in srgb, var(--semantic-danger) 56%, var(--line-strong)) !important;
  color: var(--semantic-danger) !important;
}

.delete-dialog-backdrop {
  position: fixed;
  z-index: 1000;
  inset: 0;
  display: grid;
  place-items: center;
  padding: 18px;
  background: color-mix(in srgb, var(--stage-shadow) 74%, transparent);
  backdrop-filter: blur(4px);
}
.delete-dialog {
  width: min(420px, 100%);
  padding: 20px;
  display: grid;
  grid-template-columns: 42px minmax(0, 1fr);
  gap: 12px 14px;
  border: 1px solid color-mix(in srgb, var(--semantic-danger) 42%, var(--line-strong));
  border-radius: 7px;
  color: var(--text-primary);
  background: color-mix(in srgb, var(--surface-raised) 96%, transparent);
  box-shadow:
    0 26px 80px var(--stage-shadow),
    inset 0 0 0 1px var(--line-subtle);
}
.delete-dialog-mark {
  width: 42px;
  height: 42px;
  display: grid;
  place-items: center;
  border: 1px solid color-mix(in srgb, var(--semantic-danger) 40%, transparent);
  border-radius: 50%;
  color: var(--semantic-danger);
  background: color-mix(in srgb, var(--semantic-danger) 10%, var(--surface-inset));
}
.delete-dialog-copy h2 {
  margin: 0 0 6px;
  color: var(--text-accent);
  font-size: 15px;
}
.delete-dialog-copy p {
  margin: 0;
  color: var(--text-secondary);
  font-size: 11px;
  line-height: 1.7;
}
.delete-dialog-actions {
  grid-column: 1 / -1;
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  margin-top: 4px;
}
.delete-dialog-actions button {
  min-height: 34px;
  padding: 0 13px;
  border: 1px solid var(--line-subtle);
  border-radius: 5px;
  color: var(--text-secondary);
  background: var(--surface-inset);
  cursor: pointer;
}
.delete-dialog-actions button:disabled {
  opacity: 0.48;
  cursor: wait;
}
.delete-dialog-actions .confirm-delete {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  border-color: color-mix(in srgb, var(--semantic-danger) 46%, var(--line-subtle));
  color: var(--text-primary);
  background: color-mix(in srgb, var(--semantic-danger) 18%, var(--surface-inset));
}
.delete-dialog-actions .confirm-delete:hover:not(:disabled) {
  color: #fff;
  background: var(--semantic-danger);
}

@media screen and (max-width: 760px) {
  .stage-header {
    min-height: 58px;
    grid-template-columns: auto minmax(0, 1fr) auto;
    gap: 6px;
    padding: 6px 8px;
    z-index: 40 !important;
    overflow: visible;
  }
  .scene-location {
    min-width: 0;
    padding: 4px 2px;
    display: flex;
    align-items: center;
    justify-content: center;
  }
  .scene-kicker,
  .scene-location-full {
    display: none;
  }
  .scene-location-compact {
    min-width: 0;
    max-width: 100%;
    display: flex;
    align-items: center;
    gap: 5px;
    font-size: 11px;
  }
  .scene-location-compact i {
    margin-right: 0;
  }
  .scene-location .scene-location-compact span {
    min-width: 0;
    overflow: hidden;
    color: var(--gold);
    text-overflow: ellipsis;
    white-space: nowrap;
  }
  .crane-mark {
    width: 28px;
    height: 28px;
  }
  .turn-copy span {
    display: none;
  }
  .turn-copy {
    min-width: 46px;
  }
  .turn-navigation span {
    display: none;
  }
  .stage-utilities {
    gap: 3px;
  }
  .stage-utilities .preset-button,
  .stage-utilities .greeting-index-button,
  .stage-utilities .appearance-button {
    display: none;
  }
  .reading-mode-switch {
    display: none;
  }
  .mobile-tool-group {
    position: relative;
    display: block;
    flex: 0 0 auto;
  }
  .mobile-tool-menu {
    position: absolute;
    z-index: 30;
    top: calc(100% + 13px);
    right: -38px;
    width: 148px;
    padding: 5px;
    display: grid;
    gap: 3px;
    border: 1px solid var(--line-strong);
    border-radius: 6px;
    background: color-mix(in srgb, var(--surface-raised) 96%, transparent);
    box-shadow:
      0 14px 36px color-mix(in srgb, var(--stage-shadow) 78%, transparent),
      inset 0 0 0 1px var(--line-subtle);
  }
  .mobile-tool-menu::before {
    content: '';
    position: absolute;
    top: -5px;
    right: 50px;
    width: 8px;
    height: 8px;
    border-top: 1px solid var(--line-strong);
    border-left: 1px solid var(--line-strong);
    background: var(--surface-raised);
    transform: rotate(45deg);
  }
  .stage-utilities .mobile-tool-menu button {
    width: 100%;
    height: 36px;
    display: flex;
    align-items: center;
    justify-content: flex-start;
    gap: 9px;
    padding: 0 10px;
    color: var(--text-secondary);
    white-space: nowrap;
  }
  .mobile-tool-menu button i {
    width: 16px;
    color: var(--gold);
    text-align: center;
  }
  .mobile-tool-menu button.active {
    border-color: color-mix(in srgb, var(--gold) 46%, var(--line-subtle));
    color: var(--text-primary);
    background: var(--button-active);
  }
  .mobile-tool-menu button.active i {
    color: var(--gold);
  }
  .mobile-tool-divider {
    height: 1px;
    margin: 2px 5px;
    background: linear-gradient(90deg, transparent, var(--line-strong), transparent);
  }
  .mobile-tool-menu-enter-active,
  .mobile-tool-menu-leave-active {
    transition:
      opacity 120ms ease,
      transform 120ms ease;
    transform-origin: top right;
  }
  .mobile-tool-menu-enter-from,
  .mobile-tool-menu-leave-to {
    opacity: 0;
    transform: translateY(-4px) scale(0.96);
  }
  .danger-badge {
    padding: 3px 6px;
  }
  .stage-utilities .map-button {
    display: none;
  }
  .turn-navigation button,
  .stage-utilities button {
    width: 34px;
    height: 34px;
  }
}

@media screen and (max-width: 520px) {
  .stage-header {
    min-height: 58px;
    grid-template-columns: auto minmax(0, 1fr) auto;
    grid-template-rows: none;
    align-content: normal;
    gap: 4px;
  }
  .turn-cluster {
    min-width: 0;
  }
  .turn-copy {
    min-width: 0;
    flex: 0 1 auto;
  }
  .turn-navigation {
    margin-left: 0;
    flex: 0 0 auto;
  }
  .stage-utilities {
    min-width: 0;
    justify-content: flex-end;
    gap: 3px;
  }
}

@media screen and (max-width: 450px) {
  .crane-mark {
    display: none;
  }
}

@media screen and (max-width: 390px) {
  .crane-mark,
  .danger-badge {
    display: none;
  }
  .turn-cluster {
    gap: 4px;
  }
  .turn-navigation button,
  .stage-utilities button {
    width: 30px;
  }
  .scene-location-compact {
    gap: 3px;
    font-size: 10px;
  }
}
