
.dialogue-stage {
  position: relative;
  min-width: 0;
  min-height: 0;
  height: 100%;
  display: flex;
  flex-direction: column;
  color: var(--text-primary);
  background: var(--reading-surface);
  isolation: isolate;
}
.dialogue-stage::before {
  content: '';
  position: absolute;
  inset: 0;
  z-index: 0;
  background: var(--reading-material);
  opacity: 0.76;
  pointer-events: none;
}
.dialogue-stage > * {
  position: relative;
  z-index: 1;
}

.choose-speaker-button {
  min-height: 34px;
  margin-top: 8px;
  padding: 0 14px;
  display: inline-flex;
  align-items: center;
  gap: 7px;
  border: 1px solid var(--line-strong);
  border-radius: 5px;
  color: var(--gold);
  background: var(--button-bg);
  cursor: pointer;
}
.choose-speaker-button:hover {
  background: var(--button-hover);
}

.dialogue-header {
  min-height: 48px;
  flex: none;
  padding: 6px 12px 6px 16px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  border-bottom: 1px solid var(--line-subtle);
  background: color-mix(in srgb, var(--surface-inset) 72%, transparent);
}
.speaker-heading {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 9px;
}
.channel-mark {
  width: 30px;
  height: 30px;
  flex: none;
  display: grid;
  place-items: center;
  border: 1px solid var(--line-subtle);
  border-radius: 50%;
  color: var(--jade);
  background: color-mix(in srgb, var(--jade) 8%, var(--surface-inset));
}
.transmitting .channel-mark {
  color: var(--gold);
  background: color-mix(in srgb, var(--gold) 8%, var(--surface-inset));
}
.speaker-copy {
  min-width: 0;
  display: grid;
  gap: 1px;
}
.speaker-copy small {
  color: var(--text-secondary);
  font-size: 9px;
}
.speaker-copy strong {
  overflow: hidden;
  color: var(--text-accent);
  font-family: 'Songti SC', 'STSong', serif;
  font-size: 15px;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.relation-label,
.history-badge {
  flex: none;
  padding: 3px 7px;
  border: 1px solid var(--line-subtle);
  border-radius: 999px;
  color: var(--text-secondary);
  font-size: 9px;
}
.dialogue-actions {
  display: flex;
  gap: 5px;
}
.dialogue-actions button,
.history-resume-button {
  min-height: 30px;
  padding: 0 9px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  border: 1px solid var(--line-subtle);
  border-radius: 5px;
  color: var(--text-secondary);
  background: var(--surface-inset);
  cursor: pointer;
}
.dialogue-actions button:hover:not(:disabled),
.history-resume-button:hover:not(:disabled) {
  border-color: var(--line-strong);
  color: var(--gold);
}
.dialogue-actions button:disabled,
.history-resume-button:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}
.dialogue-actions .continue-button {
  color: var(--jade);
}
.dialogue-actions .end-button {
  color: var(--gold-soft);
}
.history-resume-button {
  flex: none;
  color: var(--jade);
}

.dialogue-layout {
  min-width: 0;
  min-height: 0;
  flex: 1;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
}
.dialogue-layout.with-portrait {
  grid-template-columns: minmax(0, 1fr) clamp(210px, 21vw, 310px);
}
.dialogue-scroll-shell {
  position: relative;
  min-width: 0;
  min-height: 0;
}
.dialogue-scroll {
  width: 100%;
  height: 100%;
  min-width: 0;
  min-height: 0;
  overflow-y: auto;
  padding: clamp(22px, 4vh, 42px) clamp(18px, 5vw, 64px) 46px;
  scrollbar-color: var(--line-strong) transparent;
  scrollbar-width: thin;
}
.resume-stream-follow {
  position: absolute;
  right: 16px;
  bottom: 12px;
  z-index: 2;
  min-height: 32px;
  padding: 0 11px;
  display: inline-flex;
  align-items: center;
  gap: 7px;
  border: 1px solid var(--line-strong);
  border-radius: 999px;
  color: var(--text-accent);
  background: color-mix(in srgb, var(--surface-raised) 94%, transparent);
  box-shadow: 0 10px 28px var(--stage-shadow);
  cursor: pointer;
}
.resume-stream-follow:hover {
  color: var(--gold);
  background: var(--button-hover);
}
.dialogue-empty {
  height: 100%;
  display: grid;
  place-items: center;
  align-content: center;
  gap: 9px;
  color: var(--text-secondary);
  text-align: center;
}
.dialogue-empty i {
  color: var(--jade);
  font-size: 22px;
}
.dialogue-empty strong {
  color: var(--text-accent);
  font-family: 'Songti SC', 'STSong', serif;
}
.dialogue-empty span {
  font-size: 11px;
}

.dialogue-turn {
  width: min(82%, 760px);
  margin-bottom: 20px;
  display: flex;
  flex-direction: column;
}
.user-turn {
  margin-left: auto;
  align-items: flex-end;
}
.character-turn {
  margin-right: auto;
  align-items: flex-start;
}
.bubble-speaker,
.bubble-heading {
  margin-bottom: 5px;
  color: var(--text-secondary);
  font-size: 10px;
}
.user-bubble-heading {
  margin-bottom: 5px;
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 7px;
}
.user-bubble-heading .bubble-speaker {
  margin-bottom: 0;
}
.user-bubble-heading button {
  min-height: 21px;
  padding: 0 7px;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  border: 1px solid color-mix(in srgb, var(--gold) 24%, var(--line-subtle));
  border-radius: 999px;
  color: var(--gold-soft);
  background: color-mix(in srgb, var(--gold) 6%, var(--surface-inset));
  font-size: 9px;
  cursor: pointer;
}
.user-bubble-heading button:hover:not(:disabled) {
  border-color: color-mix(in srgb, var(--gold) 48%, var(--line-strong));
  color: var(--gold);
  background: var(--button-hover);
}
.user-bubble-heading button:disabled {
  opacity: 0.34;
  cursor: not-allowed;
}
.bubble-heading {
  width: 100%;
  min-height: 21px;
  display: flex;
  align-items: center;
  gap: 8px;
}
.bubble-heading > span:first-child {
  color: var(--text-accent);
}
.reply-token-count {
  color: var(--text-secondary);
  font-family: ui-monospace, 'SFMono-Regular', Consolas, monospace;
  font-size: 9px;
}
.bubble-heading button {
  min-height: 21px;
  padding: 0 6px;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  border: 0;
  border-radius: 4px;
  color: var(--text-secondary);
  background: color-mix(in srgb, var(--surface-inset) 70%, transparent);
  font-size: 9px;
  cursor: pointer;
}
.bubble-heading button:hover {
  color: var(--jade);
}
.bubble-heading button.reasoning-mini-trigger {
  min-height: 25px;
  padding: 3px 7px;
  border: 1px solid color-mix(in srgb, var(--jade) 28%, var(--line-subtle));
  border-radius: 999px;
  color: var(--jade);
  background:
    radial-gradient(circle at 18% 0%, color-mix(in srgb, var(--jade) 13%, transparent), transparent 48%),
    color-mix(in srgb, var(--surface-inset) 82%, transparent);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--gold) 4%, transparent);
}
.bubble-heading button.reasoning-mini-trigger:hover,
.bubble-heading button.reasoning-mini-trigger.active {
  border-color: color-mix(in srgb, var(--gold) 46%, var(--line-strong));
  color: var(--gold);
  background: color-mix(in srgb, var(--button-active) 82%, var(--surface-inset));
  box-shadow: 0 0 13px color-mix(in srgb, var(--accent-glow) 24%, transparent);
}
.reasoning-mini-time {
  padding-left: 5px;
  border-left: 1px solid color-mix(in srgb, var(--gold) 22%, transparent);
  color: var(--gold-soft);
  font-family: ui-monospace, 'SFMono-Regular', Consolas, monospace;
}
.dialogue-bubble {
  padding: 11px 14px;
  border: 1px solid var(--line-subtle);
  border-radius: 7px;
  color: var(--text-primary);
  background: color-mix(in srgb, var(--surface-raised) 88%, transparent);
  box-shadow: 0 8px 24px color-mix(in srgb, var(--stage-shadow) 18%, transparent);
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  font-family: 'Noto Serif SC', 'Source Han Serif SC', 'Songti SC', STSong, serif;
  font-size: var(--reading-font-size);
  line-height: min(var(--reading-line-height), 2);
}
.user-turn .dialogue-bubble {
  border-color: color-mix(in srgb, var(--gold) 28%, var(--line-subtle));
  background: color-mix(in srgb, var(--gold) 9%, var(--surface-inset));
}
.character-turn .dialogue-bubble {
  border-color: color-mix(in srgb, var(--jade) 24%, var(--line-subtle));
}
.dialogue-reaction {
  max-width: 92%;
  margin: 0 0 7px 3px;
  padding-left: 9px;
  border-left: 1px solid color-mix(in srgb, var(--jade) 48%, var(--line-subtle));
  color: var(--text-secondary);
  font-family: 'Noto Serif SC', 'Source Han Serif SC', 'Songti SC', STSong, serif;
  font-size: 11px;
  font-style: italic;
  line-height: 1.65;
}
.dialogue-reaction.live {
  color: color-mix(in srgb, var(--jade) 72%, var(--text-secondary));
}
.formatted :deep(p) {
  margin: 0 0 0.72em;
}
.formatted :deep(p:last-child) {
  margin-bottom: 0;
}
.formatted :deep(q) {
  quotes: none;
}
.formatted :deep(q::before),
.formatted :deep(q::after) {
  content: none;
}
.turn-reasoning,
.live-reasoning {
  width: 100%;
  margin-top: 6px;
  padding: 9px 11px;
  border-left: 2px solid var(--jade);
  color: var(--text-secondary);
  background: color-mix(in srgb, var(--surface-inset) 72%, transparent);
  font-size: 11px;
  line-height: 1.7;
}

/* Preset cards provide their own surface; keep the dialogue shell from
 * creating a second dark frame around them. */
.turn-reasoning:has(.reasoning-presentation[data-presentation='preset']) {
  padding: 0;
  border-left: 0;
  color: inherit;
  background: transparent;
}
.live-reasoning summary {
  min-height: 34px;
  padding: 4px 9px 4px 4px;
  display: flex;
  align-items: center;
  gap: 7px;
  border: 1px solid color-mix(in srgb, var(--jade) 30%, var(--line-subtle));
  border-radius: 999px;
  color: var(--text-accent);
  background:
    radial-gradient(circle at 16% 0%, color-mix(in srgb, var(--jade) 14%, transparent), transparent 46%),
    linear-gradient(110deg, color-mix(in srgb, var(--surface-raised) 90%, transparent), var(--surface-inset));
  cursor: pointer;
  list-style: none;
}
.live-reasoning summary::-webkit-details-marker {
  display: none;
}
.live-reasoning summary > .live-reasoning-glyph {
  width: 25px;
  height: 25px;
  display: grid;
  place-items: center;
  border: 1px solid color-mix(in srgb, var(--jade) 40%, transparent);
  border-radius: 50%;
  color: var(--jade);
}
.live-reasoning summary strong {
  font-family: 'Songti SC', STSong, serif;
  font-size: 10px;
  letter-spacing: 0.1em;
}
.live-reasoning summary small {
  padding-left: 7px;
  border-left: 1px solid color-mix(in srgb, var(--gold) 24%, transparent);
  color: var(--gold-soft);
  font-family: ui-monospace, 'SFMono-Regular', Consolas, monospace;
}
.live-reasoning summary > i:last-child {
  margin-left: auto;
  color: var(--text-secondary);
  font-size: 8px;
  transition: transform 0.2s ease;
}
.live-reasoning[open] summary {
  color: var(--gold);
  border-color: color-mix(in srgb, var(--gold) 52%, var(--line-strong));
  box-shadow: 0 0 16px color-mix(in srgb, var(--accent-glow) 28%, transparent);
}
.live-reasoning[open] summary > i:last-child {
  transform: rotate(180deg);
}
.live-status {
  margin-left: auto;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  color: var(--jade) !important;
}
.waiting-dots {
  min-width: 72px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
}
.waiting-dots i {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--jade);
  animation: dialogue-pulse 1.1s ease-in-out infinite;
}
.waiting-dots i:nth-child(2) {
  animation-delay: 0.14s;
}
.waiting-dots i:nth-child(3) {
  animation-delay: 0.28s;
}

.dialogue-portrait {
  min-width: 0;
  min-height: 0;
  padding: 18px;
  display: flex;
  flex-direction: column;
  gap: 12px;
  border-left: 1px solid var(--line-subtle);
  background: var(--portrait-material), color-mix(in srgb, var(--surface) 84%, transparent);
}
.portrait-frame {
  min-height: 0;
  flex: 1;
  position: relative;
  overflow: hidden;
  border: 1px solid var(--line-subtle);
  border-radius: 6px;
  background: var(--surface-inset);
  box-shadow: 0 14px 36px color-mix(in srgb, var(--stage-shadow) 55%, transparent);
}
.portrait-frame img {
  width: 100%;
  height: 100%;
  display: block;
  object-fit: contain;
}
.portrait-frame > span {
  position: absolute;
  right: 0;
  bottom: 0;
  left: 0;
  padding: 42px 12px 11px;
  display: grid;
  gap: 2px;
  color: #f3eee5;
  background: linear-gradient(to top, color-mix(in srgb, var(--surface-inset) 96%, black), transparent);
}
.portrait-frame small {
  color: #e4bd75;
  font-size: 9px;
}
.portrait-frame strong {
  font-family: 'Songti SC', 'STSong', serif;
  font-size: 17px;
}
.dialogue-portrait dl {
  margin: 0;
  padding: 9px 10px;
  border-top: 1px solid var(--line-subtle);
}
.dialogue-portrait dl div {
  display: grid;
  grid-template-columns: 38px 1fr;
  gap: 7px;
  padding: 3px 0;
  font-size: 10px;
}
.dialogue-portrait dt {
  color: var(--gold-soft);
}
.dialogue-portrait dd {
  margin: 0;
  color: var(--text-secondary);
}

@keyframes dialogue-pulse {
  0%,
  100% {
    opacity: 0.28;
    transform: translateY(0);
  }
  50% {
    opacity: 1;
    transform: translateY(-2px);
  }
}

@media screen and (max-width: 760px) {
  .dialogue-header {
    align-items: flex-start;
  }
  .relation-label {
    display: none;
  }
  .dialogue-actions button span {
    display: none;
  }
  .dialogue-actions button {
    width: 31px;
    padding: 0;
  }
  .history-resume-button span {
    display: none;
  }
  .history-resume-button {
    width: 31px;
    padding: 0;
  }
  .dialogue-layout.with-portrait {
    grid-template-columns: minmax(0, 1fr);
    grid-template-rows: 112px minmax(0, 1fr);
  }
  .dialogue-portrait {
    grid-row: 1;
    padding: 9px 12px;
    display: grid;
    grid-template-columns: 78px minmax(0, 1fr);
    border-bottom: 1px solid var(--line-subtle);
    border-left: 0;
  }
  .portrait-frame {
    grid-row: 1;
    min-height: 92px;
  }
  .portrait-frame > span {
    padding: 26px 7px 6px;
  }
  .portrait-frame strong {
    font-size: 12px;
  }
  .dialogue-portrait dl {
    align-self: center;
    border-top: 0;
  }
  .dialogue-scroll-shell {
    grid-row: 2;
  }
  .dialogue-scroll {
    padding: 20px 13px 34px;
  }
  .resume-stream-follow {
    right: 9px;
    bottom: 9px;
  }
  .dialogue-turn {
    width: 92%;
    margin-bottom: 15px;
  }
  .dialogue-bubble {
    padding: 9px 11px;
  }
}

.historical .dialogue-scroll {
  padding-bottom: 28px;
}
